import sys,json
p=sys.stdin.read().split('\n===SEP===\n')
d=json.loads(p[0]) if p[0].strip() else {}
iss=json.loads(p[1]) if len(p)>1 and p[1].strip() else {}
want=sys.argv[1].strip().lower()
cols={k.strip().lower():v for k,v in json.loads(sys.argv[2] or '{}').items()}
cur=((iss.get('fields') or {}).get('status') or {}).get('name') or ''
if cur.strip().lower()==want:
    sys.stdout.write('DEJA')
    sys.exit(0)
tr=d.get('transitions') or []
to=lambda t:((t.get('to') or {}).get('name') or '').strip().lower()
ts=[t for t in tr if to(t)==want]
col=cols.get(cur.strip().lower())
if not ts and sys.argv[3]=='via' and col:
    ts=[t for t in tr if to(t)!=cur.strip().lower() and cols.get(to(t))==col]
rank={k:i for i,k in enumerate(cols)}
ts.sort(key=lambda t:(bool(t.get('isGlobal')),rank.get(to(t),99)))
if not ts:
    have=', '.join(sorted({(t.get('to') or {}).get('name') or '?' for t in tr}))
    sys.stderr.write('Jira ne propose pas de passer de %s a %s (possibles : %s).\n' % (cur or '?', sys.argv[1], have or 'aucune'))
    sys.exit(1)
sys.stdout.write(str(ts[0]['id']))

